export function lessonById(id){return CURRICULUM.find(l=>l.id===id);}
export function nearLessonTarget(aim,target){return Math.hypot(aim.x-target.x,aim.y-target.y)<=4;}
export function readLessonCompletion(raw){try{const v=JSON.parse(raw);return [CURRICULUM_VERSION,'lessons-v1-baseline-v6'].includes(v?.version)&&Array.isArray(v.completed)?[...new Set(v.completed.filter(id=>lessonById(id)))]:[];}catch{return[];}}
export function lessonFixture(lesson){const fixture=lesson.guided;return{...fixture,drawSeed:7142026};}
